  let g = neon[nI][1]+(neon[nI+1][1]-neon[nI][1])*nF;
  let b = neon[nI][2]+(neon[nI+1][2]-neon[nI][2])*nF;
  const glow = 0.7 + Math.sin(reaction*Math.PI)*0.3;
  r *= glow; g *= glow; b *= glow;
  if (uiTotal > 0) {
    const uiR = 0, uiG = 220 + Math.sin(t*2)*35, uiB = 255;
    const uiMix = Math.min(uiTotal, 1);
    r = r*(1-uiMix) + uiR*uiMix;
    g = g*(1-uiMix) + uiG*uiMix;
    b = b*(1-uiMix) + uiB*uiMix;
